// ── ✨ particulas-voxel · LIBRERÍA: voxeles que saltan, caen y se quedan ──────────────────────────
// No hace nada al correr. Se usa desde otro snippet:
//
//     const P = await game.snippet('particulas-voxel');
//     const chispas = P.crea({ grupo:'chispas', chorro:14, dura:2, colores:[[1,0.85,0.3]] });
//     chispas.salpica([x, y, z]);
//
// Salió de REQ-SANGRE1: la sangre de la espada eran 170 líneas, de las que solo 12 hablaban de
// sangre. Esto es las otras 158. Un efecto nuevo son ~8 líneas de configuración.
//
// ────────────────────────────────────────────────────────────────────────────────────────────────
// DÓNDE SE DIBUJA
// En `game.voxelesUI`, la capa de ADORNO: cubos de color de 1/16 de bloque que **no son mundo** — no
// colisionan, no se guardan, no salen en la foto del mapa y se pierden al recargar. Cada efecto pide
// su `grupo`, así que limpiar uno no toca a los demás ni a lo que haya plantado nadie a mano.
// ⚠️ `mcVoxUIGeom` remalla la capa ENTERA en cuanto algo cambia, así que:
//    · se repinta el grupo entero cada frame (llevar la cuenta voxel a voxel no ahorraría nada), y
//    · el bucle solo la ensucia los frames en los que algo se ha movido de verdad. Con todo posado
//      no cuesta nada, y en cuanto no queda ninguna partícula el rAF SE APAGA SOLO.
//
// UN SOLO BUCLE PARA TODOS LOS EFECTOS
// No es un rAF por efecto: hay uno global (`window.__vfParticulas`) que recorre los sistemas vivos.
// Diez efectos a la vez siguen siendo un requestAnimationFrame. Reejecutar este snippet cancela el
// bucle anterior, así se puede retunear desde el editor sin dejar dos simulaciones peleándose.

const M = window.__vfParticulas || (window.__vfParticulas = { sistemas: [], raf: 0, on: false });
if(M.raf) cancelAnimationFrame(M.raf);
M.on = false;

const S = await game.snippet('sondas-mundo');    // ⬅️ las sondas por FORMA viven en su propio fichero

const POR_DEFECTO = {
  grupo: 'particulas',   // su sitio en game.voxelesUI; dos efectos con el mismo grupo se pisan
  activa: true,
  chorro: 20,            // cuántas salen por cada salpica()
  dura: 8,               // segundos POSADA en el suelo, de reloj
  desvanece: 2,          // los últimos N de esos segundos, oscureciéndose
  grav: 24,              // bloques/s². Negativa = sube (humo)
  fuerza: 5.5,           // velocidad de salida
  hacia: 'mirada',       // 'mirada' (rebota hacia el jugador), 'radial' (esfera), 'arriba' (columna)
  rebote: 0.22,          // cuánto conserva al chocar
  roza: 0.45,            // cuánto conserva EN HORIZONTAL al tocar suelo
  parada: 1.1,           // por debajo de esta velocidad vertical, se posa
  disperso: 0.14,        // radio del punto de salida, en bloques
  tope: 500,             // partículas vivas como mucho
  // >1 ⇒ lo POSADO se dibuja en su propio grupo («<grupo>:posada») y con el cubo así de gordo. No son
  // más voxeles: `grosor` agranda el CUBO, no el paso, así que tapa grosor² veces más suelo GRATIS.
  // Es la única forma de que se vea la alfombra sin pagarla, porque el remallado de la capa es POR
  // VOXEL (medido: 1,28 µs cada uno, lineal hasta 16 000). 0 = apagado: a la sangre y a las chispas
  // engordarlas al tocar les sienta fatal, y son la mayoría.
  grosorPosada: 0,
  // ── CUAJAR EN EL MALLADO DEL MUNDO ─────────────────────────────────────────────────────────────
  // El que se posa DEJA de ser partícula y se hornea en el mallado del mundo TAL CUAL ES: el mismo
  // voxel de 1/16 y el mismo color. No hay material de por medio ⇒ vale para nieve, ceniza, sangre o
  // lo que sea, y no hay salto visible al tocar el suelo (que es lo que pasaba cuajando en un bloque
  // de 16³: «se convierte en un bloque de 16x16x16», el dueño).
  //
  // Es la única forma de que la escena se llene de verdad. Aquí, en la capa viva, lo posado se remalla
  // ENTERO cada frame y se sube a la GPU cada frame: 1,28 µs por voxel ⇒ 8 000 copos = 10,8 ms/frame.
  // Horneado va troceado por chunk, con su VBO ya subido: cae un copo y se rehace SOLO su chunk, una
  // vez, y los demás frames son un drawArrays. El coste por frame no depende de cuántos haya.
  //
  // No se guarda en el .vox del dueño: los voxeles finos no son materia, son adorno del mundo.
  // Con `cuaja` puesto, `dura` es lo que la alfombra aguanta EN EL SUELO y `tope` solo limita lo que VUELA.
  cuaja: false,
  cuajaTope: 20000,      // voxeles cuajados a la vez como mucho; pasado eso se derrite lo más viejo
  // ── EL MANTO ─────────────────────────────────────────────────────────────────────────────────
  // `cuaja` hornea CADA COPO donde cayó, y eso sirve para lo disperso (unas gotas de sangre, cuatro
  // chispas). Para NEVAR NO SIRVE, y está medido: un copo es un voxel de 1/16, o sea 1/256 de la cara
  // de un bloque; con 55 copos/s durante 2 minutos salía un recuadro de 26×28 bloques —la caja de
  // siembra— cubierto al 2,6 %. Es lo que cazó el dueño en la foto #60.
  //
  // El manto NO es la suma de los copos. Es un espesor por COLUMNA DE BLOQUE que sube con el tiempo
  // en toda la zona a la vez, en orden aleatorio: la escena se llena entera y el borde queda
  // deshilachado en vez de recto. Los copos son el efecto que ves caer; el manto es lo que cuaja.
  //
  // Cada columna es UNA CELDA achatada con la textura del material (`game.volatiles.ponCapa`): el
  // bloque de arriba, aplastado a `manto`/16 de alto. Son ~2 quads, y van en la pasada del terreno.
  // ⬅️ ESPESOR de la alfombra, en voxeles finos (1/16 de bloque cada uno): 2 = una lámina fina,
  // 8 = media cara de bloque, 16 = un bloque entero. 0 = este efecto no cuaja manto.
  // Se puede cambiar en caliente —la configuración ES el sistema— y la alfombra se reajusta sola:
  //   P.sistemas.find(s => s.grupo === 'nieve').manto = 3;
  manto: 0,
  mantoEn: 50,           // segundos de nevada hasta llegar a ese espesor
  mantoDura: 120,        // segundos en derretirse del todo cuando para de nevar
  mantoRadio: 0,         // radio en bloques alrededor del jugador; 0 = TODO el mapa
  mantoPorFrame: 400,    // columnas que cambian como mucho en un frame, para que no dé un tirón
  // ⚠️ El manto NO usa `cuajaRitmo`/`cuajaChunks`: ése es el presupuesto de los bloques volátiles de
  // 16³, que cuestan ~2 ms de remallado cada uno. Un chunk FINO cuesta 0,17 ms (medido, 218 cajas),
  // doce veces menos. Con el ritmo de los gordos el mapa tardaba 9 s en refrescarse entero y la nieve
  // salía A CUADRADOS DE CHUNK — el «aparece todo de golpe» del dueño era eso, literalmente.
  muereEnFluido: true,   // ⬅️ el copo se deshace al TOCAR agua o lava, no se hunde hasta el fondo
  mantoSobreFluido: false, // ⬅️ por defecto la nieve NO cuaja sobre agua ni lava: se hunde y ya.
                         // Lo realista sería que la SUPERFICIE se fuera helando; eso es otra cosa
                         // (un material, no un manto) y hoy no se hace.
  // ⬅️ DE QUÉ ES LA ALFOMBRA: el MATERIAL, tal cual lo escribiría setVoxel ('nieve', 'oro', 'hab:…',
  // 'asset:assets/snow.vox.json'). Se dibuja con SU TEXTURA, la misma que tendría el bloque entero.
  // Se puede cambiar en caliente y la alfombra se repinta sola.
  mantoDe: 'nieve',
  mantoRevisaPorFrame: 600, // columnas que se repasan por frame, por si el mundo ha cambiado
  mantoChunks: 6,        // chunks de alfombra remallados por pasada
  mantoRitmo: 0.1,       // segundos entre esas pasadas
  cuajaRitmo: 0.25,      // segundos entre remallados: agrupa la ráfaga en una pasada
  // ⬅️ EL MANDO DE FPS. Remallar un chunk cuesta ~2 ms y una nevada ensucia 9 a la vez: de golpe son
  // 43 ms por segundo, de uno en uno 8. Lo único que se pierde es que un chunk tarde un par de
  // segundos en enseñar su nieve, y la nieve cae despacio de todas formas.
  cuajaChunks: 1,        // chunks remallados por pasada como mucho (0 = todos)
  vuelo: 8,              // segundos volando como mucho, en tiempo SIMULADO
  posarse: true,         // false = no se posa nunca; al tocar algo, desaparece (chispas, humo)
  deriva: 0,             // vaivén horizontal mientras cae, en bloques/s (la nieve, no la lluvia)
  derivaHz: 0.5,         // cada cuánto cambia de lado ese vaivén
  colores: [[1, 1, 1]],

  // ── EMISIÓN CONTINUA (ambiente: nieve, lluvia, ceniza) ──────────────────────────────────────
  // Con `porSegundo > 0` el sistema deja de ser un chorro y pasa a llover sobre el jugador: cada
  // frame siembra partículas nuevas en una caja que VIAJA CON ÉL, así que el efecto no se queda
  // atrás al andar y no hay que sembrar el mapa entero (que es lo que lo haría inviable).
  porSegundo: 0,         // 0 = no es ambiente, es un chorro (salpica)
  radio: 14,             // media anchura de esa caja, en bloques
  alto: 12,              // a qué altura sobre el jugador aparecen
  fondo: 24              // por debajo de jugador−fondo se recogen (se han ido por un barranco)
};

function crea(cfg){
  const C = Object.assign({}, POR_DEFECTO, cfg || {});
  const V = [];                                    // las partículas vivas de ESTE sistema
  // Grupo aparte para lo cuajado: es lo que permite que el copo que CAE sea una mota fina y el que ya
  // está en el suelo sea un cubo gordo, con un solo voxel cada uno. `grosor` es ajuste del grupo, se
  // pone una vez y sobrevive a limpia().
  const GP = C.grupo + ':posada';
  if(C.grosorPosada > 1 && game.voxelesUI) game.voxelesUI.grosor(GP, C.grosorPosada);

  function posa(g, ahora){ g.vx = g.vy = g.vz = 0; g.posada = ahora; }

  // ── Lo cuajado (ver `cuaja` en la config) ───────────────────────────────────────────────────────
  // La cola es PLANA y en orden de llegada: [fx, fy, fz, cuándo, …] en unidades de 1/16 de bloque, las
  // mismas de `game.voxelesUI`. Plana porque son decenas de miles y un objeto por copo son decenas de
  // miles de objetos; en orden porque derretir es siempre por la cabeza, nunca hay que buscar.
  const Q = [];
  let sucio = false, ultRemalla = 0;
  function cuajaOn(){ return !!(C.cuaja && game.volatiles && game.volatiles.ponFino); }
  // El copo se hornea DONDE ESTÁ y COMO ESTÁ: misma celda fina, mismo color. Por eso no se ve el
  // cambio — para el ojo no pasa nada, solo deja de moverse.
  function hornea(g, ahora){
    const p = 1 / S.MC_T;
    const fx = Math.floor(g.x/p), fy = Math.floor(g.y/p), fz = Math.floor(g.z/p);
    // Dos copos en la misma celda fina son UN voxel: la capa es un mapa por celda. Eso es también lo
    // que impide que se apilen torres, porque lo horneado no es sólido y el siguiente copo cae hasta
    // el mismo sitio.
    if(!game.volatiles.ponFino(fx, fy, fz, g.col)) return false;
    Q.push(fx, fy, fz, ahora); sucio = true;
    return true;
  }
  // Derretir lo viejo y remallar la ráfaga. Va aparte del paso porque es lo ÚNICO caro de esto: sin
  // agrupar, cada copo que se posa pagaría su propio remallado de chunk.
  function deshiela(ahora){
    if(!Q.length && !sucio) return;
    let n = 0;
    while(Q.length && (ahora - Q[3] >= C.dura || Q.length / 4 > C.cuajaTope)){
      game.volatiles.quitaFino(Q[0], Q[1], Q[2]); Q.splice(0, 4); sucio = true;
      if(++n > 400) break;     // un deshielo grande se reparte entre frames en vez de dar un tirón
    }
    if(sucio && ahora - ultRemalla >= C.cuajaRitmo){
      sucio = game.volatiles.remalla(C.cuajaChunks) > 0;   // devuelve los que QUEDAN por remallar
      ultRemalla = ahora;
    }
  }
  function deshielaTodo(){
    while(Q.length){ if(game.volatiles) game.volatiles.quitaFino(Q[0], Q[1], Q[2]); Q.splice(0, 4); }
    if(game.volatiles) game.volatiles.remalla();
    sucio = false;
  }

  // ── EL MANTO (ver `manto` en la config) ─────────────────────────────────────────────────────────
  // Un espesor por columna de bloque. `nivel` va de 0 a `manto` y es el espesor MEDIO; las columnas
  // no suben todas la vez, suben en un orden barajado fijo, así que en mitad de la nevada hay claros
  // y manchas y el borde no es recto. Barajar UNA vez y guardar el orden es lo que hace que esto sea
  // O(lo que cambia) y no O(columnas) por frame.
  //
  // El truco de la posición: `mp` es «cuántos pasos de columna se han dado ya», y un paso es subirle
  // 1/16 a UNA columna. Paso s ⇒ columna `orden[s % N]`, espesor `(s/N|0)+1`. Subiendo, s avanza;
  // derritiendo, retrocede por el mismo camino. No hay que buscar nada ni ordenar nada.
  const Mto = { x:null, y:null, z:null, orden:null, esp:null, n:0, nivel:0, p:0, radio:-1,
                remallado:0, rev:0 };
  function mantoOn(){ return !!(C.manto > 0 && game.volatiles && game.volatiles.ponCajaFina
                                && typeof mc !== 'undefined' && mc.grid); }
  // ¿Hay líquido en esta celda? Contesta `game.fluidos`, que es quien sabe de niveles (`hab:agua-3`)
  // y de tipos. ⛔ NUNCA por el nombre del material: antes esto era un /agua|water|lava/ sobre la
  // clave, y el motor lo prohíbe expresamente («aquí no se reconoce ningún material por su nombre»).
  //
  // Memorizado por id porque el bucle de partículas lo pregunta cientos de veces por frame y
  // `getProps` se come varias expresiones regulares en cada llamada. Es exacto: `isFluid` sale sólo
  // del id —la posición nada más le sirve para el NIVEL, que aquí no se usa—. La caché se tira si
  // crece la paleta.
  const fluIds = new Map();
  let fluN = -1;
  function esFluido(x, y, z){
    if(typeof mc === 'undefined' || !mc.grid) return false;
    const d = mc.dim, bx = Math.floor(x), by = Math.floor(y), bz = Math.floor(z);
    if(bx < 0 || by < 0 || bz < 0 || bx >= d.x || by >= d.y || bz >= d.z) return false;
    const id = mc.grid[mcIdx(bx, by, bz)];
    if(!id) return false;
    const n = mc.blockKey ? mc.blockKey.length : 0;
    if(n !== fluN){ fluN = n; fluIds.clear(); }
    let f = fluIds.get(id);
    if(f === undefined){
      const api = (typeof game !== 'undefined') && game.fluidos;
      const p = (api && typeof api.getProps === 'function') ? api.getProps(id, bx, by, bz) : null;
      f = !!(p && p.isFluid);
      fluIds.set(id, f);
    }
    return f;
  }
  function mantoFluido(x, y, z){ return C.mantoSobreFluido ? false : esFluido(x, y, z); }

  // Se construye una vez (y otra si cambia el radio o el mundo). `mcSurfaceY` es O(alto) y esto son
  // miles de columnas: ~5 ms de una sentada, contra hacerlo por frame que sería inviable.
  function mantoConstruye(){
    const dim = mc.dim, R = C.mantoRadio | 0;
    let x0 = 0, x1 = dim.x - 1, z0 = 0, z1 = dim.z - 1;
    if(R > 0){
      const px = Math.floor(mc.pos[0]), pz = Math.floor(mc.pos[2]);
      x0 = Math.max(0, px - R); x1 = Math.min(dim.x - 1, px + R);
      z0 = Math.max(0, pz - R); z1 = Math.min(dim.z - 1, pz + R);
    }
    const xs = [], ys = [], zs = [];
    for(let z = z0; z <= z1; z++) for(let x = x0; x <= x1; x++){
      // Se baja desde lo más alto hasta el primer bloque que AGUANTA nieve encima, y por el camino se
      // descarta la columna si hay fluido.
      //
      // ⚠️ `mcSurfaceY` da lo más ALTO haya lo que haya, y eso NO es donde se posa la nieve: sobre una
      // planta, unas hojas o una valla ponía la baldosa en la cima del adorno, flotando (la captura de
      // la planta con la losa encima, el dueño). `mcTapaCara` es la pregunta buena y ya está en el
      // motor: es falsa para los bloques de recorte y para los de geometría fina —los que tienen
      // huecos y solo caras pintadas— y verdadera para un cubo de verdad.
      //
      // ⚠️ Y el fluido hay que mirarlo AQUÍ DENTRO, bajando, no al final: `mcTapaCara` también es falso
      // para el agua, así que sin esto la columna seguía bajando y el manto acababa EN EL FONDO DE LA
      // PISCINA, que es lo que se veía a través del agua en la captura del dueño.
      let y = mcSurfaceY(x, z), moja = false;
      while(y >= 0){
        if(mantoFluido(x, y, z)){ moja = true; break; }
        if(mcTapaCara(x, y, z)) break;
        y--;
      }
      if(moja || y < 0 || y >= dim.y - 1) continue;   // mojada, columna vacía, o llena hasta el techo
      xs.push(x); ys.push(y); zs.push(z);
    }
    const n = xs.length;
    Mto.x = Int32Array.from(xs); Mto.y = Int32Array.from(ys); Mto.z = Int32Array.from(zs);
    Mto.esp = new Uint8Array(n); Mto.n = n; Mto.nivel = 0; Mto.p = 0; Mto.radio = R; Mto.rev = 0;
    // Fisher-Yates: el orden en que van blanqueando. Sin esto la nieve avanzaría en barrido, como una
    // persiana de norte a sur, que es peor que el recuadro.
    const o = new Int32Array(n);
    for(let i = 0; i < n; i++) o[i] = i;
    for(let i = n - 1; i > 0; i--){ const j = (Math.random() * (i + 1)) | 0; const t = o[i]; o[i] = o[j]; o[j] = t; }
    Mto.orden = o;
    return n;
  }

  // El color del manto: el del efecto, con una pizca de variación por columna. Sin la variación una
  // alfombra plana de un solo blanco se ve como un plástico.
  // ── DE QUÉ ESTÁ HECHA LA ALFOMBRA ────────────────────────────────────────────────────────────
  // Una celda del terreno ACHATADA a `manto`/16 de alto, con la TEXTURA de `mantoDe`. La pone
  // `game.volatiles.ponCapa`, que no es materia: no choca, no tapa la luz y no se guarda.
  //
  // ⚠️ Antes esto eran CAJAS DE COLOR de la capa fina, y con ellas la textura no había manera:
  // copiarla pide 16×16 = 256 cajas por bloque —la del oro es ruido, 248 baldosas distintas de 256, no
  // se funden— o sea 2 millones de cajas y ~2 GB para el mapa entero. Achatada son ~2 quads por
  // bloque, y como va en la pasada del terreno hereda la niebla y la sombra del sol, que a la capa
  // fina no le llegaban (el manto se veía a todo color contra el horizonte gris).
  function mantoMat(){ return String(C.mantoDe || 'nieve').trim() || 'nieve'; }

  // La columna crece POR ALTURA, un 1/16 por paso, hasta `manto`. La gradación de antes (mancha de
  // 8×8 → 12×12 → baldosa de 16×16) era cosa de las cajas: una celda achatada cubre su bloque entero.
  // Lo que sigue impidiendo que la nevada se «encienda» de golpe es el orden aleatorio de las columnas.
  function mantoPasos(){ return Math.max(1, C.manto | 0); }
  function mantoQuita(i){
    if(Mto.y[i] >= 0) game.volatiles.quitaCapa(Mto.x[i], Mto.y[i] + 1, Mto.z[i]);
  }
  function mantoPone(i, e){
    if(e > 0 && Mto.y[i] >= 0) game.volatiles.ponCapa(Mto.x[i], Mto.y[i] + 1, Mto.z[i], e, Mto.mat);
  }
  function mantoPon(i, e){
    if(Mto.y[i] < 0){ Mto.esp[i] = 0; return; }    // columna retirada (sin suelo o mojada): no hay dónde
    if(e > 0) mantoPone(i, e); else mantoQuita(i);
    Mto.esp[i] = e;
  }
  // ¿está ese material EN LA PALETA de este mundo? Si no lo está, `ponCapa` pinta ROCA — no es cosa
  // suya, es lo que hace `setVoxel` con un material desconocido, y así salió una nevada de oro
  // entera de piedra en /map/test.
  function mantoHayMat(m){
    const k = mcMatKey(m, m.toLowerCase());
    return mc.blockKey.indexOf(k) > 0 || (mc.name2id && mc.name2id[m] > 0);
  }
  // Cambiar `mantoDe` en caliente: se repone lo que ya estaba con el material nuevo. `ponCapa` pisa la
  // celda, así que no hace falta quitar antes. Es un tirón de una vez (~7 800 celdas) y solo al
  // cambiar el mando, no por frame.
  //
  // Lo que sí puede tardar es TRAER el material: `game.addMaterial` descarga el dibujo y hace crecer
  // el atlas. Mientras llega, las columnas que crezcan se pintan de roca; por eso el repintado va
  // DESPUÉS del await y arregla también esas.
  async function mantoRepinta(){
    const m = Mto.mat = mantoMat();
    if(!mantoHayMat(m)){
      try{ await game.addMaterial(mcMatKey(m, m.toLowerCase())); }
      catch(e){ console.warn('[manto] no he podido cargar «' + m + '»', e); }
      if(Mto.mat !== m) return;                      // lo han vuelto a cambiar mientras cargaba
    }
    if(Mto.n) for(let i = 0; i < Mto.n; i++) if(Mto.esp[i]) mantoPone(i, Mto.esp[i]);
  }

  // ⛏️ EL MUNDO SE EDITA MIENTRAS NIEVA. La altura de cada columna se calcula una vez y luego solo se
  // mueve el espesor; si picas el bloque de debajo, la baldosa se queda FLOTANDO donde estaba su techo
  // (el dueño). Así que las columnas se repasan POR TURNOS y la que ha cambiado se vuelve a sentar
  // sobre lo que haya ahora.
  //
  // El repaso es O(1) por columna: `mcTapaCara` donde se apoya y una lectura de la celda de encima. La
  // bajada cara —la de `mantoConstruye`— la paga solo la columna que ha cambiado, o sea las cuatro que
  // acabas de picar. Con 600 por frame y 7 839 columnas el mapa entero se repasa en ~13 frames.
  //
  // ⚠️ No se engancha a «romper bloque» a propósito: así vale igual para una explosión, para el agua
  // que sube o para lo que plante otro snippet, y no hay que envolver nada del motor.
  function mantoRevisa(){
    const cuantos = Math.min(Mto.n, C.mantoRevisaPorFrame | 0);
    if(cuantos <= 0) return;
    const dim = mc.dim;
    for(let k = 0; k < cuantos; k++){
      const i = Mto.rev; Mto.rev = (Mto.rev + 1) % Mto.n;
      const x = Mto.x[i], y = Mto.y[i], z = Mto.z[i];
      if(y < 0) continue;                          // ya retirada
      // Sin novedad: sigue apoyada y sigue con el hueco de encima libre. Éste es el caso del 99,9 %
      // de las columnas y es lo único que se paga por frame.
      if(mcTapaCara(x, y, z) && !mc.grid[mcIdx(x, y + 1, z)]) continue;
      let ny = mcSurfaceY(x, z), moja = false;     // ha cambiado: se vuelve a bajar, como al construir
      while(ny >= 0){
        if(mantoFluido(x, ny, z)){ moja = true; break; }
        if(mcTapaCara(x, ny, z)) break;
        ny--;
      }
      if(ny === y && !moja) continue;              // era una planta o algo que no aguanta: sigue igual
      const e = Mto.esp[i];
      mantoPon(i, 0);                              // quita la baldosa de donde estaba
      Mto.y[i] = (moja || ny < 0 || ny >= dim.y - 1) ? -1 : ny;
      mantoPon(i, e);                              // y la pone abajo con el MISMO espesor (o nada)
    }
  }
  function manto(dt, ahora){
    if(!mantoOn()){ if(Mto.n) mantoLimpia(); return; }
    // ⛔ Reconstruir sin limpiar deja HUÉRFANAS las cajas de las columnas de antes: `mantoLimpia`
    // recorre las columnas ACTUALES, así que las que salen del radio ya no las conoce nadie y se
    // quedan pintadas para siempre (medido: 30 300 cajas al bajar `mantoRadio` en caliente).
    if(Mto.n && Mto.radio !== (C.mantoRadio | 0)) mantoLimpia();
    if(!Mto.n) if(!mantoConstruye()) return;
    if(Mto.mat !== mantoMat()) mantoRepinta().catch(e => console.warn('[manto] material', e));
    mantoRevisa();
    const N = Mto.n, PASOS = mantoPasos();
    // Nevando sube, parado baja. El manto NO depende de dónde caigan los copos: por eso cuaja también
    // donde no estás mirando, que es justo lo que faltaba.
    const sube = C.porSegundo > 0;
    Mto.nivel += (sube ? PASOS / Math.max(0.1, C.mantoEn) : -PASOS / Math.max(0.1, C.mantoDura)) * dt;
    Mto.nivel = Math.max(0, Math.min(PASOS, Mto.nivel));
    const objetivo = Math.round(Mto.nivel * N);
    let tope = C.mantoPorFrame | 0;
    while(Mto.p < objetivo && tope-- > 0){ const s = Mto.p++; mantoPon(Mto.orden[s % N], (s / N | 0) + 1); }
    while(Mto.p > objetivo && tope-- > 0){ const s = --Mto.p; mantoPon(Mto.orden[s % N], (s / N | 0)); }
    // Presupuesto PROPIO de remallado, no el de los bloques gordos: ver `mantoChunks` en la config.
    if(ahora - Mto.remallado >= C.mantoRitmo){
      game.volatiles.remalla(C.mantoChunks | 0);
      Mto.remallado = ahora;
    }
  }
  function mantoLimpia(){
    if(Mto.n && game.volatiles) for(let i = 0; i < Mto.n; i++) if(Mto.esp[i]) mantoPon(i, 0);
    Mto.n = 0; Mto.nivel = 0; Mto.p = 0; Mto.radio = -1;
    Mto.x = Mto.y = Mto.z = Mto.orden = Mto.esp = null;
    if(game.volatiles) game.volatiles.remalla();
  }

  // Un paso. Devuelve si ALGO ha cambiado (o sea, si hay que repintar).
  function paso(dt, ahora){
    // Una vez por frame, para las cientos de sondas de este bucle: la lista de cajas de lo estampado.
    // Es el contrato de `sondas-mundo` — sin esta línea todo sigue funcionando, solo que cada sonda
    // vuelve a recorrer `mc.structures` entera (medido: 9,2 µs por sonda, 1,91 ms por frame).
    if(S.refrescaEstructuras) S.refrescaEstructuras();
    const CJ = cuajaOn();      // id del material que cuaja, o 0 si este efecto no cuaja
    manto(dt, ahora);          // el suelo: no depende de los copos, ver `manto` en la config
    deshiela(ahora);
    let cambia = false;
    for(let i = V.length - 1; i >= 0; i--){
      const g = V[i];
      if(g.posada){
        const vida = ahora - g.posada;
        if(vida >= C.dura){ V.splice(i, 1); cambia = true; continue; }
        // El desvanecido es lo único que hace trabajar a una partícula quieta, y solo al final.
        const f = (vida > C.dura - C.desvanece) ? Math.max(0.15, (C.dura - vida) / C.desvanece) : 1;
        if(f !== g.f){ g.f = f; cambia = true; }
        continue;
      }
      // ⚠️ El vuelo se cuenta en tiempo SIMULADO (sumando `dt`), no de reloj. Con `dt` acotado, en
      // una máquina a pocos fps un segundo de reloj es una fracción de segundo de caída: midiendo
      // por reloj se matan partículas que aún están en el aire (medido: 16 de 22 en swiftshader).
      // El descanso en el suelo, en cambio, SÍ es de reloj: «30 segundos» son 30 segundos.
      if((g.vuela = (g.vuela || 0) + dt) > C.vuelo){ V.splice(i, 1); cambia = true; continue; }
      const v = Math.hypot(g.vx, g.vy, g.vz);
      // Subpasos de como mucho medio voxel fino: a 5 bloques/s un frame entero se salta el suelo.
      let n = Math.max(1, Math.min(24, Math.ceil(v * dt / (S.MC_T ? 0.5 / S.MC_T : 0.03))));
      // El vaivén de la nieve: no es física, es un empujón lateral que va y viene. Cada copo lleva
      // su propia fase (`g.fase`) o todos irían a la vez y se vería la fila.
      if(C.deriva){
        const w = (ahora + g.fase) * C.derivaHz * Math.PI * 2;
        g.vx = Math.cos(w) * C.deriva; g.vz = Math.sin(w * 0.7) * C.deriva;
      }
      // ⚠️ FASE GRUESA — es lo único que separa la lluvia de ser injugable ────────────────────────
      // Trocear el paso cuesta una sonda al mundo POR TROZO, y cada sonda recorre `mc.structures`
      // entero. Lo caro es la velocidad, no la cantidad: la lluvia va a ~40 bloques/s y topaba en
      // los 24 trozos siempre (medido: 61 gotas, 1 371 sondas/frame, 11 ms de CPU antes de dibujar
      // nada; la nieve, con 420 copos pero 7 veces más lenta, iba a 1 trozo). Pero una gota que
      // cae por el aire no choca con nada en TODO el tramo, y eso se puede preguntar de una vez:
      // si la caja del tramo está limpia, se avanza entero con una sonda en lugar de 22.
      // El troceo NO desaparece: en cuanto la caja roza algo, se vuelve a él y el choque se
      // resuelve con la misma precisión de medio voxel fino que antes.
      // Y si la caja sale limpia, la sonda de dentro del bucle sobra POR CONSTRUCCIÓN: el tramo
      // entero está dentro de esa caja, así que preguntar nunca podría contestar otra cosa. Ese
      // `libre` es la mitad del ahorro de la nieve, que va despacio y solo troceaba en 4.
      let libre = false, ahoga = false;
      if(n > 1){
        const ex = g.x + g.vx*dt, ey = g.y + (g.vy - C.grav*dt)*dt, ez = g.z + g.vz*dt,
              m = 2 / (S.MC_T || 16);   // margen: la curva del troceo cae dentro de esta caja
        if(S.cajaVacia(Math.min(g.x,ex)-m, Math.min(g.y,ey)-m, Math.min(g.z,ez)-m,
                       Math.max(g.x,ex)+m, Math.max(g.y,ey)+m, Math.max(g.z,ez)+m)){ n = 1; libre = true; }
      }
      const h = dt / n;
      for(let k = 0; k < n; k++){
        g.vy -= C.grav * h;
        const nx = g.x + g.vx*h, ny = g.y + g.vy*h, nz = g.z + g.vz*h;
        // El copo se deshace al TOCAR el líquido; no lo atraviesa hasta el lecho («deberían
        // desaparecer nada más tocar un fluido», el dueño, con la foto del fondo de la piscina).
        // ⚠️ Se mira aunque el tramo vaya `libre`: un fluido NO es sólido, así que ni `S.solido` ni
        // la caja rápida lo ven y ése es justo el caso del agua.
        if(C.muereEnFluido && esFluido(nx, ny, nz)){ ahoga = true; break; }
        if(!libre && S.solido(nx, ny, nz)){
          if(!C.posarse){ V.splice(i, 1); cambia = true; break; }   // chispas, humo: se apagan al tocar
          if(S.solido(g.x, ny, g.z)){                 // suelo (o techo): rebota poco y se frena
            g.vy = -g.vy * C.rebote; g.vx *= C.roza; g.vz *= C.roza;
            if(Math.abs(g.vy) < C.parada){ posa(g, ahora); break; }
          }else{                                       // pared: se escurre por ella
            if(S.solido(nx, g.y, g.z)) g.vx = -g.vx * C.rebote;
            if(S.solido(g.x, g.y, nz)) g.vz = -g.vz * C.rebote;
          }
          // Y la salida de emergencia: en un rincón puede tocar en diagonal sin que ninguna de las
          // dos ramas de arriba la pose, y entonces se queda volando para siempre.
          if((g.atasco = (g.atasco || 0) + 1) > 12){ posa(g, ahora); break; }
          continue;
        }
        g.x = nx; g.y = ny; g.z = nz; g.atasco = 0;
      }
      // ⚠️ Borrar dentro del sub-bucle y hacer `break` deja al código de abajo mirando una `g` que ya
      // no está en `V`, y su `V.splice(i,1)` se llevaría por delante a OTRA partícula. Bandera fuera.
      if(ahoga){ V.splice(i, 1); cambia = true; continue; }
      // Se acaba de posar y este efecto cuaja: se hornea en la malla del mundo y deja de ser
      // partícula. Con esto lo posado no ocupa `tope` ni se repinta: el copo se paga UNA vez.
      if(CJ && g.posada){ hornea(g, ahora); V.splice(i, 1); cambia = true; continue; }
      // Se ha ido por un barranco o el jugador se ha alejado: se recoge. Sin esto, andar bajo la
      // nieve va dejando un rastro de copos vivos a la espalda y el `tope` se come el efecto.
      if(!g.posada && typeof mc !== 'undefined' && mc.pos){
        if(g.y < mc.pos[1] - C.fondo || Math.abs(g.x - mc.pos[0]) > C.radio * 2
                                     || Math.abs(g.z - mc.pos[2]) > C.radio * 2){
          V.splice(i, 1); cambia = true; continue;
        }
      }
      cambia = true;
    }
    return cambia;
  }

  // Fuera la posada MÁS VIEJA, para hacerle sitio a una nueva. Devuelve si ha podido.
  // El barrido es O(vivas) y se hace ~2 veces por frame con 55 copos/s: son ~3 µs, y a cambio la
  // nieve no se para. Llevar una cola ordenada por antigüedad costaría más de mantener que esto.
  function reciclaPosada(){
    let peor = -1, masVieja = Infinity;
    for(let i = 0; i < V.length; i++){
      const g = V[i];
      if(g.posada && g.posada < masVieja){ masVieja = g.posada; peor = i; }
    }
    if(peor < 0) return false;
    V.splice(peor, 1);
    return true;
  }

  // Siembra de ambiente: `porSegundo` partículas en una caja que viaja con el jugador. Se guarda el
  // resto fraccionario (`deuda`) o con dt pequeño y pocas por segundo no saldría ninguna nunca.
  let deuda = 0;
  function siembra(dt, ahora){
    if(!C.porSegundo || typeof mc === 'undefined' || !mc.pos) return false;
    deuda += C.porSegundo * dt;
    let n = Math.floor(deuda); if(n <= 0) return false;
    deuda -= n;
    // ⚠️ AL LLEGAR AL CUPO SE RECICLA, NO SE DEJA DE SEMBRAR. Antes esta línea ponía `n = 0` y la
    // nieve SE PARABA: los posados duran `dura` segundos y se comen el cupo entero (55/s × 25 s =
    // 1375 posados para sostenerla, contra un tope de 420), así que el efecto nevaba 8 s y se
    // quedaba 21 SEGUNDOS sin un copo en el aire, en ciclo —la primera tanda entra junta y caduca
    // junta—. Reciclando, lo que se derrite es lo que cuajó primero, que es lo que hace la nieve.
    // ⚠️ Solo se recicla lo POSADO: quitar una partícula en el aire sería verla desaparecer.
    // ⚠️ Y la cuenta que queda: con el cupo apretado, lo posado ya no llega a durar `dura`, dura lo
    // que el cupo deje. Para las dos cosas hay que subir `tope`, y eso se paga en el remallado de
    // la capa, que es POR VOXEL. `dura` vuelve a mandar en cuanto el cupo no aprieta.
    if(V.length + n > C.tope){
      for(let k = V.length + n - C.tope; k > 0; k--){
        if(!reciclaPosada()) break;      // todo volando: entonces sí manda el tope, sin más
      }
      if(V.length + n > C.tope) n = Math.max(0, C.tope - V.length);
    }
    for(let i = 0; i < n; i++){
      V.push({
        x: mc.pos[0] + (Math.random()*2 - 1) * C.radio,
        y: mc.pos[1] + C.alto * (0.7 + Math.random() * 0.3),
        z: mc.pos[2] + (Math.random()*2 - 1) * C.radio,
        vx: 0, vy: -C.fuerza * (0.6 + Math.random() * 0.8), vz: 0,
        col: C.colores[(Math.random() * C.colores.length) | 0],
        fase: Math.random() * 10, nace: ahora, posada: 0, f: 1
      });
    }
    return n > 0;
  }

  // Se repinta el grupo entero: son pocas y así no hay que llevar la cuenta de qué voxel ocupaba
  // cada partícula el frame anterior. El `tam` es de la capa global, así que el paso se lee de ella.
  function pinta(){
    const U = game.voxelesUI; if(!U) return;
    const gordo = C.grosorPosada > 1;
    U.limpia(C.grupo); if(gordo) U.limpia(GP);
    const p = (1 / S.MC_T) * Math.max(1, U.tam | 0);
    for(const g of V){
      const c = g.col, f = g.f === undefined ? 1 : g.f;
      // El cubo gordo crece hacia +x/+y/+z desde su esquina, así que lo cuajado se apila HACIA ARRIBA
      // sobre la cara en la que se paró: es lo que se quiere, no hay que recolocar nada.
      // ⚠️ Lo cuajado se ajusta a la retícula del cubo GORDO, y NO es por ahorrar: medido, colapsa 1,0
      // copos por voxel con `radio: 13` —caen repartidos por 26×26 bloques y casi nunca coinciden en la
      // misma placa—, así que ahí no ahorra nada; solo ahorra si la nieve se amontona en poco sitio.
      // Es para que la alfombra quede EMBALDOSADA en vez de hecha de cubos solapados a 1/16 de bloque:
      // es lo que la hace parecer hielo y no espuma. La capa es un mapa POR CELDA, así que dos copos en
      // la misma placa son una sola clave y un solo voxel.
      if(gordo && g.posada){
        const q = C.grosorPosada;
        U.pon(Math.floor(g.x/(p*q))*q, Math.floor(g.y/(p*q))*q, Math.floor(g.z/(p*q))*q,
              [c[0]*f, c[1]*f, c[2]*f], GP);
      }else{
        U.pon(Math.floor(g.x/p), Math.floor(g.y/p), Math.floor(g.z/p), [c[0]*f, c[1]*f, c[2]*f], C.grupo);
      }
    }
  }

  // Hacia dónde salen. 'mirada' es lo de la sangre: al revés de por donde ha entrado el filo.
  function empuje(){
    if(C.hacia === 'arriba') return [0, 1, 0];
    if(C.hacia === 'radial'){
      const t = Math.random() * Math.PI * 2, u = Math.random() * 2 - 1, r = Math.sqrt(1 - u*u);
      return [Math.cos(t) * r, u, Math.sin(t) * r];
    }
    const cp = Math.cos(mc.pitch || 0);
    return [Math.sin(mc.yaw || 0) * cp, 0.75, Math.cos(mc.yaw || 0) * cp];
  }

  const api = Object.assign(C, {
    // salpica(punto) — punto del mundo: [x,y,z]. Devuelve cuántas han salido.
    salpica(p, cuantas){
      if(!C.activa || !p || !game.voxelesUI) return 0;
      const ahora = performance.now() / 1000, n = cuantas || C.chorro, e = empuje();
      for(let i = 0; i < n; i++){
        const f = C.fuerza * (0.35 + Math.random() * 0.9);
        V.push({
          x: p[0] + (Math.random()-0.5) * C.disperso,
          y: p[1] + (Math.random()-0.5) * C.disperso,
          z: p[2] + (Math.random()-0.5) * C.disperso,
          vx: (e[0] + (Math.random()-0.5) * 0.9) * f * 0.9,
          vy: (e[1] * (0.3 + Math.random() * 0.9)) * f * 0.75,
          vz: (e[2] + (Math.random()-0.5) * 0.9) * f * 0.9,
          col: C.colores[(Math.random() * C.colores.length) | 0],
          fase: Math.random() * 10, nace: ahora, posada: 0, f: 1
        });
      }
      while(V.length > C.tope) V.shift();
      arranca();
      return n;
    },
    // Ambiente: empieza/para la siembra continua. `enciende(0)` = parar sin borrar lo que ya cae.
    enciende(porSegundo){
      if(porSegundo !== undefined) C.porSegundo = Math.max(0, +porSegundo || 0);
      else if(!C.porSegundo) C.porSegundo = POR_DEFECTO.porSegundo || 40;
      C.activa = true; arranca(); return C.porSegundo;
    },
    para(){ C.porSegundo = 0; return this; },
    // Alias de `para()`. Los emisores paran y las capas de game.voxelesUI (estrellas) apagan;
    // conviven en el mismo menú de `game.efectos`, así que quien viene de `estrellas.apaga()`
    // escribe `luciernagas.apaga()` y se comía un «no es una función». Entiende las dos.
    // (por `C` y no por `this`: el objeto es `C` —`const api = Object.assign(C, {...})`— y así
    // un `const f = L.apaga` suelto tampoco se rompe.)
    apaga(){ return C.para(); },
    limpia(){ V.length = 0; deuda = 0;
      mantoLimpia();
      deshielaTodo();          // lo cuajado es del mundo: si no se quita aquí, se queda ahí para siempre
      if(game.voxelesUI){ game.voxelesUI.limpia(C.grupo); game.voxelesUI.limpia(GP); }
      return 0; },
    // Bloques cuajados vivos. Lo mira el bucle global: mientras queden hay que seguir dando pasos
    // aunque no vuele ni un copo, o la última nevada no se derretiría nunca.
    cuajadas(){ return Q.length / 4 + Mto.p; },
    info(){ let posadas = 0;
      for(const g of V) if(g.posada) posadas++;
      return { grupo: C.grupo, vivas: V.length, posadas, volando: V.length - posadas,
               bucle: M.on, activa: C.activa, dura: C.dura, chorro: C.chorro,
               porSegundo: C.porSegundo, manto: C.manto, mantoDe: C.mantoDe,
               mantoCeldas: Mto.n }; },
    _paso: paso, _siembra: siembra, _pinta: pinta, _V: V
  });

  // Un sistema con el mismo grupo SUSTITUYE al anterior: reejecutar el snippet que lo define no
  // deja dos simulaciones pintando en la misma capa.
  const ya = M.sistemas.findIndex(s => s.grupo === C.grupo);
  if(ya >= 0) M.sistemas[ya] = api; else M.sistemas.push(api);
  return api;
}

function arranca(){
  if(M.on) return;
  M.on = true;
  let prev = performance.now();
  const tick = () => {
    if(!M.on) return;
    const t = performance.now(), dt = Math.min(0.05, (t - prev) / 1000); prev = t;
    let vivas = 0, lloviendo = 0;
    for(const s of M.sistemas){
      if(!s.activa){ vivas += s._V.length; continue; }
      const sembrado = s._siembra(dt, t / 1000);
      if(s._paso(dt, t / 1000) || sembrado) s._pinta();
      vivas += s._V.length + (s.cuajadas ? s.cuajadas() : 0); lloviendo += s.porSegundo ? 1 : 0;
    }
    // Ni un rAF girando en vacío… pero un ambiente encendido sin partículas (aún) sigue vivo.
    if(!vivas && !lloviendo){ M.on = false; return; }
    M.raf = requestAnimationFrame(tick);
  };
  M.raf = requestAnimationFrame(tick);
}

return { crea, arranca, sistemas: M.sistemas, porDefecto: POR_DEFECTO,
  info(){ return M.sistemas.map(s => s.info()); },
  limpia(){ for(const s of M.sistemas) s.limpia(); M.on = false;
            if(M.raf) cancelAnimationFrame(M.raf); return M.sistemas.length; } };
